CREATE FUNCTION public.migration_research_page_v1(p_table text,p_after jsonb DEFAULT NULL,p_limit integer DEFAULT 500,p_offset integer DEFAULT 0)
RETURNS json LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path='' AS $body$
DECLARE q text; result json; expected_keys integer;
BEGIN
 IF current_user <> 'service_role' THEN RAISE EXCEPTION 'Service role required' USING ERRCODE='42501'; END IF;
 IF p_limit IS NULL OR p_limit<1 OR p_limit>500 OR p_offset IS NULL OR p_offset<0 THEN RAISE EXCEPTION 'Invalid page limits'; END IF;
 CASE p_table
 WHEN 'research.area' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."area_id"), ''[]''::json) FROM (SELECT * FROM "research"."area" WHERE ($1 IS NULL OR ROW("area_id") > ROW(($1->>0)::uuid)) ORDER BY "area_id" LIMIT $2) r';
