WHEN 'research.claim' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."claim_id"), ''[]''::json) FROM (SELECT * FROM "research"."claim" WHERE ($1 IS NULL OR ROW("claim_id") > ROW(($1->>0)::uuid)) ORDER BY "claim_id" LIMIT $2) r';
WHEN 'research.claim_version' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."claim_version_id"), ''[]''::json) FROM (SELECT * FROM "research"."claim_version" WHERE ($1 IS NULL OR ROW("claim_version_id") > ROW(($1->>0)::uuid)) ORDER BY "claim_version_id" LIMIT $2) r';
