WHEN 'research.computation_run' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."computation_run_id"), ''[]''::json) FROM (SELECT * FROM "research"."computation_run" WHERE ($1 IS NULL OR ROW("computation_run_id") > ROW(($1->>0)::uuid)) ORDER BY "computation_run_id" LIMIT $2) r';
WHEN 'research.coverage_assessment' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."coverage_assessment_id"), ''[]''::json) FROM (SELECT * FROM "research"."coverage_assessment" WHERE ($1 IS NULL OR ROW("coverage_assessment_id") > ROW(($1->>0)::uuid)) ORDER BY "coverage_assessment_id" LIMIT $2) r';
