WHEN 'research.dataset' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."dataset_id"), ''[]''::json) FROM (SELECT * FROM "research"."dataset" WHERE ($1 IS NULL OR ROW("dataset_id") > ROW(($1->>0)::uuid)) ORDER BY "dataset_id" LIMIT $2) r';
