WHEN 'research.impact_channel' THEN expected_keys := 2; q := 'SELECT coalesce(json_agg(r ORDER BY r."source_mechanism_id",r."target_mechanism_id"), ''[]''::json) FROM (SELECT * FROM "research"."impact_channel" WHERE ($1 IS NULL OR ROW("source_mechanism_id","target_mechanism_id") > ROW(($1->>0)::bigint,($1->>1)::bigint)) ORDER BY "source_mechanism_id","target_mechanism_id" LIMIT $2) r';
WHEN 'research.impact_external_revision' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."revision_id"), ''[]''::json) FROM (SELECT * FROM "research"."impact_external_revision" WHERE ($1 IS NULL OR ROW("revision_id") > ROW(($1->>0)::uuid)) ORDER BY "revision_id" LIMIT $2) r';
WHEN 'research.impact_input_binding' THEN expected_keys := 2; q := 'SELECT coalesce(json_agg(r ORDER BY r."model_key",r."input_key"), ''[]''::json) FROM (SELECT * FROM "research"."impact_input_binding" WHERE ($1 IS NULL OR ROW("model_key","input_key") > ROW(($1->>0)::text,($1->>1)::text)) ORDER BY "model_key","input_key" LIMIT $2) r';
WHEN 'research.impact_model' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."model_key"), ''[]''::json) FROM (SELECT * FROM "research"."impact_model" WHERE ($1 IS NULL OR ROW("model_key") > ROW(($1->>0)::text)) ORDER BY "model_key" LIMIT $2) r';
WHEN 'research.impact_model_run' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."computation_run_id"), ''[]''::json) FROM (SELECT * FROM "research"."impact_model_run" WHERE ($1 IS NULL OR ROW("computation_run_id") > ROW(($1->>0)::uuid)) ORDER BY "computation_run_id" LIMIT $2) r';
WHEN 'research.impact_model_theme' THEN expected_keys := 2; q := 'SELECT coalesce(json_agg(r ORDER BY r."model_key",r."theme_id"), ''[]''::json) FROM (SELECT * FROM "research"."impact_model_theme" WHERE ($1 IS NULL OR ROW("model_key","theme_id") > ROW(($1->>0)::text,($1->>1)::integer)) ORDER BY "model_key","theme_id" LIMIT $2) r';
WHEN 'research.impact_point' THEN expected_keys := 4; q := 'SELECT coalesce(json_agg(r ORDER BY r."computation_run_id",r."year",r."factor_key",r."group_key"), ''[]''::json) FROM (SELECT * FROM "research"."impact_point" WHERE ($1 IS NULL OR ROW("computation_run_id","year","factor_key","group_key") > ROW(($1->>0)::uuid,($1->>1)::integer,($1->>2)::text,($1->>3)::text)) ORDER BY "computation_run_id","year","factor_key","group_key" LIMIT $2) r';
WHEN 'research.impact_release' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."release_id"), ''[]''::json) FROM (SELECT * FROM "research"."impact_release" WHERE ($1 IS NULL OR ROW("release_id") > ROW(($1->>0)::uuid)) ORDER BY "release_id" LIMIT $2) r';
WHEN 'research.impact_run_check' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."computation_run_id"), ''[]''::json) FROM (SELECT * FROM "research"."impact_run_check" WHERE ($1 IS NULL OR ROW("computation_run_id") > ROW(($1->>0)::uuid)) ORDER BY "computation_run_id" LIMIT $2) r';
