WHEN 'research.impact_theme_year' THEN expected_keys := 3; q := 'SELECT coalesce(json_agg(r ORDER BY r."release_id",r."theme_id",r."year"), ''[]''::json) FROM (SELECT * FROM "research"."impact_theme_year" WHERE ($1 IS NULL OR ROW("release_id","theme_id","year") > ROW(($1->>0)::uuid,($1->>1)::integer,($1->>2)::integer)) ORDER BY "release_id","theme_id","year" LIMIT $2) r';
WHEN 'research.indicator' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."indicator_id"), ''[]''::json) FROM (SELECT * FROM "research"."indicator" WHERE ($1 IS NULL OR ROW("indicator_id") > ROW(($1->>0)::uuid)) ORDER BY "indicator_id" LIMIT $2) r';
WHEN 'research.indicator_definition' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."indicator_definition_id"), ''[]''::json) FROM (SELECT * FROM "research"."indicator_definition" WHERE ($1 IS NULL OR ROW("indicator_definition_id") > ROW(($1->>0)::uuid)) ORDER BY "indicator_definition_id" LIMIT $2) r';
WHEN 'research.observation' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."observation_id"), ''[]''::json) FROM (SELECT * FROM "research"."observation" WHERE ($1 IS NULL OR ROW("observation_id") > ROW(($1->>0)::uuid)) ORDER BY "observation_id" LIMIT $2) r';
WHEN 'research.open_question' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."open_question_id"), ''[]''::json) FROM (SELECT * FROM "research"."open_question" WHERE ($1 IS NULL OR ROW("open_question_id") > ROW(($1->>0)::uuid)) ORDER BY "open_question_id" LIMIT $2) r';
WHEN 'research.period' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."period_id"), ''[]''::json) FROM (SELECT * FROM "research"."period" WHERE ($1 IS NULL OR ROW("period_id") > ROW(($1->>0)::uuid)) ORDER BY "period_id" LIMIT $2) r';
WHEN 'research.plot' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."plot_id"), ''[]''::json) FROM (SELECT * FROM "research"."plot" WHERE ($1 IS NULL OR ROW("plot_id") > ROW(($1->>0)::smallint)) ORDER BY "plot_id" LIMIT $2) r';
WHEN 'research.research_case' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."case_id"), ''[]''::json) FROM (SELECT * FROM "research"."research_case" WHERE ($1 IS NULL OR ROW("case_id") > ROW(($1->>0)::uuid)) ORDER BY "case_id" LIMIT $2) r';
WHEN 'research.research_task' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."research_task_id"), ''[]''::json) FROM (SELECT * FROM "research"."research_task" WHERE ($1 IS NULL OR ROW("research_task_id") > ROW(($1->>0)::uuid)) ORDER BY "research_task_id" LIMIT $2) r';
