WHEN 'research.revision_basis' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."revision_basis_id"), ''[]''::json) FROM (SELECT * FROM "research"."revision_basis" WHERE ($1 IS NULL OR ROW("revision_basis_id") > ROW(($1->>0)::uuid)) ORDER BY "revision_basis_id" LIMIT $2) r';
WHEN 'research.source' THEN expected_keys := 1; q := 'SELECT coalesce(json_agg(r ORDER BY r."source_id"), ''[]''::json) FROM (SELECT * FROM "research"."source" WHERE ($1 IS NULL OR ROW("source_id") > ROW(($1->>0)::uuid)) ORDER BY "source_id" LIMIT $2) r';
