 ELSE RAISE EXCEPTION 'Table not allowed';
 END CASE;
 IF p_after IS NOT NULL THEN
  IF jsonb_typeof(p_after)<>'array' THEN RAISE EXCEPTION 'Invalid cursor'; END IF;
  IF jsonb_array_length(p_after)<>expected_keys OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_after) v WHERE v='null'::jsonb) THEN RAISE EXCEPTION 'Invalid cursor'; END IF;
 END IF;
 EXECUTE q INTO result USING p_after,p_limit;
 RETURN result;
END;
$body$;
REVOKE ALL ON FUNCTION public.migration_research_page_v1(text,jsonb,integer,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.migration_research_page_v1(text,jsonb,integer,integer) TO service_role;
GRANT SELECT ON "research"."area","research"."area_classification","research"."area_mapping","research"."audit_log","research"."card_citation","research"."card_evidence_assessment","research"."card_section","research"."card_version","research"."claim","research"."claim_version","research"."coverage_assessment","research"."coverage_cell","research"."coverage_evidence","research"."evidence_kind_exception","research"."evidence_link","research"."hypothesis","research"."hypothesis_test","research"."hypothesis_version","research"."indicator","research"."indicator_definition","research"."observation","research"."open_question","research"."period","research"."plot","research"."research_case","research"."research_task","research"."revision_basis","research"."source_locator","research"."source_type" TO service_role;
